    if (expectedPrice == 0) return 0;

    uint256 priceDifference = expectedPrice > actualPrice 
        ? expectedPrice - actualPrice 
        : actualPrice - expectedPrice;

    return (priceDifference * _SLIPPAGE_DENOMINATOR) / expectedPrice;
